-- V98: Add AI admin health reports table
-- Stores periodic health reports generated by AI admins summarizing activity,
-- galaxy status, and LLM-generated recommendations.

CREATE TABLE ai_admin_health_reports (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    ai_admin_id BIGINT NOT NULL,
    report_type VARCHAR(10) NOT NULL,
    period_start DATETIME NOT NULL,
    period_end DATETIME NOT NULL,
    generated_at DATETIME NOT NULL,
    orders_processed INT NOT NULL DEFAULT 0,
    orders_completed INT NOT NULL DEFAULT 0,
    orders_failed INT NOT NULL DEFAULT 0,
    incidents_handled INT NOT NULL DEFAULT 0,
    xp_earned INT NOT NULL DEFAULT 0,
    galaxy_health_score INT,
    active_incidents INT NOT NULL DEFAULT 0,
    summary TEXT,
    recommendations TEXT,
    llm_analysis TEXT
);

CREATE INDEX idx_aahr_admin ON ai_admin_health_reports(ai_admin_id);
CREATE INDEX idx_aahr_type ON ai_admin_health_reports(report_type);
CREATE INDEX idx_aahr_period ON ai_admin_health_reports(period_start);
CREATE INDEX idx_aahr_generated ON ai_admin_health_reports(generated_at);
